CREATE TABLE `admin_jurisdiction_audits` (`id` text PRIMARY KEY NOT NULL,`friction_id` text NOT NULL,`generation_id` text NOT NULL,`jurisdiction` text NOT NULL,`normalized_jurisdiction` text NOT NULL,`agency` text,`status` text DEFAULT 'ACQUISITION_REQUIRED' NOT NULL,`source_count` integer DEFAULT 0 NOT NULL,`metric_count` integer DEFAULT 0 NOT NULL,`authority_text` text,`authority_source_url` text,`observed_text` text,`observed_source_url` text,`discrepancy_text` text,`missing_proof` text,`source_urls_json` text DEFAULT '[]' NOT NULL,`errors_json` text DEFAULT '[]' NOT NULL,`started_at` text,`completed_at` text,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE UNIQUE INDEX `admin_jurisdiction_audits_friction_uidx` ON `admin_jurisdiction_audits` (`friction_id`);
CREATE INDEX `admin_jurisdiction_audits_status_idx` ON `admin_jurisdiction_audits` (`status`,`updated_at`);
